def scene() -> Scene:
    return Scene(
        id="real-rock",
        terrain="unknown",
        season="summer",
        seed=1,
        zoom=1,
        camera=(0, 0),
        viewport=(625, 330),
        tile_width=64,
        frames=(),
    )


def test_real_qa039_cut_is_detected() -> None:
    image = np.asarray(Image.open(BytesIO(base64.b64decode(ROCK))).convert("RGB"))
    findings = detect_rock_cuts(image, scene(), Thresholds())
    assert findings
    assert findings[0].box.width > 400
    assert findings[0].detector == "straight_boundary"


def test_masked_real_rock_abstains() -> None:
    image = np.asarray(Image.open(BytesIO(base64.b64decode(ROCK))).convert("RGB"))
    assert not detect_rock_cuts(image, scene(), Thresholds(), np.zeros(image.shape[:2], np.uint8))


def test_uniform_gray_and_curved_rock_abstain() -> None:
    image = np.full((330, 625, 3), (100, 130, 60), np.uint8)
    yy, xx = np.indices(image.shape[:2])
    oval = ((xx - 300) / 230) ** 2 + ((yy - 160) / 120) ** 2 < 1
    noise = np.random.default_rng(1).integers(90, 150, image.shape[:2], dtype=np.uint8)
    image[oval] = np.repeat(noise[:, :, None], 3, axis=2)[oval]
    assert not detect_rock_cuts(image, scene(), Thresholds())
    assert not detect_rock_cuts(np.full_like(image, 120), scene(), Thresholds())


def test_real_black_border_stamps_have_tile_periodicity() -> None:

    image = np.asarray(Image.open(BytesIO(base64.b64decode(ROCK))).convert("RGB"))
    findings = detect_rock_seams(image, scene(), Thresholds())
    assert findings
    assert findings[0].detector == "tile_seam"


def test_cut_without_dark_stamps_is_not_a_seam() -> None:

    image = np.asarray(Image.open(BytesIO(base64.b64decode(ROCK))).convert("RGB")).copy()
    image[image.mean(axis=2) < 70] = (100, 85, 40)
    assert detect_rock_cuts(image, scene(), Thresholds())
    assert not detect_rock_seams(image, scene(), Thresholds())


