def test_real_scattered_boulders_are_not_cut_patches() -> None:
    image = np.asarray(Image.open(BytesIO(base64.b64decode(HEALTHY_ROCK))).convert("RGB"))
    assert not detect_rock_cuts(image, scene(), Thresholds())
    assert not detect_rock_seams(image, scene(), Thresholds())
